import type { CDNConfigRules } from './interfaces';
import { VideoInfo, VideoMetaData, IParsingRules, VideoInfoAndMetadata } from './interfaces';
import { VIDEO_PROVIDER, MESSAGE_TYPES, VIDEO_PROVIDER_INFO } from './constants';
import mediaMetaDataExtractorCS from './MediaMetaDataExtractorCS';
import { VideoURLParser } from './VideoURLParser';
import { YoutubeDOMParser } from './YoutubeDOMParser';
import { VimeoDOMParser } from './VimeoDOMParser';
import { DomObserver } from './DomObserver';
import uiController from './UIController';
import helperUtils from './utils/HelperUtils';

class VideoDownloaderCS {
  private videoURLParser?: VideoURLParser;
  private rules?: Record<string, any>;
  private videoProvider?: VIDEO_PROVIDER;
  private isInitialized = false;
  private domParsingRules: string[];
  private urlParsingRules: IParsingRules;
  private domObserver: DomObserver;
  private lastProcessedVideoId?: string;
  constructor() {
    this.onPlayerFound = this.onPlayerFound.bind(this);
    this.domObserver = new DomObserver();
  }


  async init(): Promise<void> {
        // Request parsing rules/config from background script
        const rules = await new Promise<Record<string, any> | undefined>((resolve) => {
            chrome.runtime.sendMessage({ type: MESSAGE_TYPES.GET_PARSING_RULES }, (response) => {
                if (response && response.success && response.config) {
                    resolve(response.config);
                } else {
                     console.error('[VideoDownloaderCS] Failed to load parsing rules from background:', response?.error);
                    resolve(undefined);
                }
            });
        });
        if (!rules) {
          console.error('[VideoDownloaderCS] No rules received, aborting init');
            this.isInitialized = false;
            return;
        }
        this.rules = rules;
        this.isInitialized = true;
        // Get provider, domParsingRules, and videoIdRegex for the current hostname
        const { provider, domParsingRules, videoIdRegex } = helperUtils.getProviderAndDomParsingRules(rules as CDNConfigRules);
        this.videoProvider = provider;
        this.domParsingRules = domParsingRules;
        switch(provider) {
          case VIDEO_PROVIDER.YOUTUBE:
            this.videoURLParser = domParsingRules
                    ? new VideoURLParser(new YoutubeDOMParser(domParsingRules), videoIdRegex)
                    : undefined;
            break;
          case VIDEO_PROVIDER.VIMEO:
            this.videoURLParser = domParsingRules
                    ? new VideoURLParser(new VimeoDOMParser(domParsingRules), videoIdRegex)
                    : undefined;
            break;
          default:
            break;
        }
    }

  /**
   * Determines whether a MutationObserver is required for the specified video provider.
   *
   * @param videoProvider - The video provider to check. This should be one of the values from the VIDEO_PROVIDER enum.
   * @returns `true` if a MutationObserver is required for the given video provider, otherwise `false`.
   */
  private isMutationObserverRequired(videoProvider: VIDEO_PROVIDER): boolean {
    return VIDEO_PROVIDER_INFO[videoProvider]['isMutationObserverRequired'];
  }

  /**
   * Handles the event when a video player is found.
   * This method initiates the process of fetching video information and metadata
   * using the provided URL parsing rules.
   *
   * @private
   */
  private onPlayerFound() {
    this.domObserver.unobserveDom();
    this.fetchVideoInfoAndMetadata(this.urlParsingRules)
  }

  async runVideoDetection(): Promise<void> {
    try {
      await this.init();
      const providerConfig = this.videoProvider && this.rules?.videoProviders?.[this.videoProvider];
      const urlParsingRules = providerConfig?.urlParsingRules;
      if (urlParsingRules) {
        this.urlParsingRules = { urlParsingRules };
        if (this.isMutationObserverRequired(this.videoProvider)) {
          this.domObserver.observeDom(this.domParsingRules, this.onPlayerFound);
          return;
        }
        await this.fetchVideoInfoAndMetadata({ urlParsingRules });
      }
    } catch (e) {
      console.error('Error loading parsing rules:', e);
    }
  }

  private async fetchVideoInfoAndMetadata(urlParsingRules: IParsingRules): Promise<void> {
    const videoInfo = await this.parseDOM(urlParsingRules);
    if (!videoInfo) return;
    if (this.lastProcessedVideoId === videoInfo.videoId) {
      return;
    }
    this.lastProcessedVideoId = videoInfo.videoId;
    const metadata = await this.getVideoMetaData(videoInfo);
    const videoInfoAndMetadata = {metadata, videoInfo};
    uiController.renderPlayerUI(videoInfoAndMetadata);
  }

  async parseDOM(parsingRules: IParsingRules): Promise<VideoInfo | null> {
    if (!this.videoURLParser) {
      return null;
    }
    const info = await this.videoURLParser.parseURL(parsingRules);
    if (info) {
      console.log('videoId:', info.videoId);
    }
    return info;
  }

  async getVideoMetaData(videoInfo: VideoInfo): Promise<VideoMetaData> {
    const metaData: VideoMetaData = await mediaMetaDataExtractorCS.getVideoMetaData(videoInfo.videoId, this.videoProvider);
    return metaData;
  }

  downloadMedia(videoInfo: VideoInfo): void {
  }


  /**
   * Handles incoming messages from other parts of the extension.
   * 
   * @param message - The message object containing the type and data of the request.
   * @param sender - The sender of the message, provided by the Chrome runtime.
   * @param sendResponse - A callback function to send a response back to the sender.
   * @returns A promise that resolves when the message is processed.
   */
  async handleMessages(message: any, sender: chrome.runtime.MessageSender, sendResponse: (response: any) => void): Promise<void> {
    if (!this.isInitialized) {
      await this.init();    }
    try {
      if (
        message.type === MESSAGE_TYPES.TAB_URL_CHANGED &&
        message.url
      ) {
        await this.runVideoDetection();
        sendResponse({ success: true });
        return;
      }
      // TODO: handle messages here.
    } catch (error) {
      console.error('[CS] Error in handleMessages:', error);
      sendResponse({ success: false, error: error.message });
    }
  }

  /**
   * Called on DOM load to start video detection and metadata extraction.
   */
  async onDOMLoad(): Promise<void> {
    await this.runVideoDetection();
  }

  /**
   * Initializes listeners for handling runtime messages.
   */
  initListeners(): void {
    chrome.runtime.onMessage.addListener(async (message, sender, sendResponse) => {
      try {
        await this.handleMessages(message, sender, sendResponse);
      } catch (error) {
        console.error('Error handling message:', error);
        sendResponse({ success: false, error: error.message });
      }
      return true;
    });
  }
}

const videoDownloaderCS = new VideoDownloaderCS();

function initializeVideoDownloaderCS() {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', async () => {
      await videoDownloaderCS.onDOMLoad();
    });
  } else {
    videoDownloaderCS.onDOMLoad();
  }
}

initializeVideoDownloaderCS();
videoDownloaderCS.initListeners();
export default videoDownloaderCS;