import type { DOMParser, IParsingRules, VideoInfo } from './interfaces';

export class VideoURLParser {
  private domParser: DOMParser;
  private videoIdRegex?: string;

  constructor(domParser: DOMParser, videoIdRegex?: string) {
    this.domParser = domParser;
    this.videoIdRegex = videoIdRegex;
  }

  async parseURL(parsingRules: IParsingRules): Promise<VideoInfo | null> {
    // Use the DOMParser interface for all logic
    if (!this.domParser.hasPlayer()) {
      return null;
    }
    const tabUrl: string = window?.location?.href || '';
    // If parsingRules is missing or empty, return null
    if (!parsingRules || !parsingRules.urlParsingRules || parsingRules.urlParsingRules.length === 0) {
      return null;
    }
    if (!tabUrl) {
      return null;
    }
    const videoId = this.domParser.getVideoId(parsingRules, tabUrl);
    console.log('[VideoURLParser] getVideoId result:', videoId);
    if (!videoId || !this.videoIdRegex) {
      return null;
    }
    const validator = new RegExp(this.videoIdRegex);
    if (!validator.test(videoId)) {
      return null;
    }
    const playerSelectors = this.domParser.getPlayerSelectors();
    return {
      videoId,
      tabUrl,
      playerSelectors
    };
  }
}

export default VideoURLParser;
