import React, { useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { Provider, useSelector, useDispatch } from 'react-redux';
import { UiUtils } from './utils/UiUtils';
import { VideoMetaData, VideoInfo, VideoInfoAndMetadata, UIType } from './interfaces';
import { VIDEO_DOWNLOADER_GLOBAL_POPUP_ROOT_ID } from './constants';
import DownloadMenu from './ui/components/DownloadMenu';
import { DownloadProgressProvider } from './ui/components/DownloadProgressContext';
import { MESSAGE_TYPES, REDUX_ACTIONS } from './constants';
import { Store } from 'webext-redux';
import { TELEMETRY_LABEL } from './telemetry/telemetryConstants';

class UIController {
    constructor() {
    }
    static playerRoot: ReturnType<typeof createRoot> | null = null;

    static getOrCreateGlobalPopupRoot() {
        let root = document.getElementById(VIDEO_DOWNLOADER_GLOBAL_POPUP_ROOT_ID);
        if (!root) {
            root = document.createElement('div');
            root.id = VIDEO_DOWNLOADER_GLOBAL_POPUP_ROOT_ID;
            document.body.appendChild(root);
        }
        return root;
    }

    static renderUI(type: UIType, payload?: { metadata?: VideoMetaData, videoInfo?: VideoInfo }) {
        let root: ReturnType<typeof createRoot>;
        let rootElement: HTMLElement;
        if (type === UIType.PLAYER) {
            rootElement = UiUtils.createRootElement();
            if (!UIController.playerRoot) {
                UIController.playerRoot = createRoot(rootElement);
            }
            root = UIController.playerRoot;
        } else {
            throw new Error('Unknown UIType');
        }
        const proxyStore = new Store();
        proxyStore.ready().then(() => {
            if (type === UIType.PLAYER && payload && payload.videoInfo) {
                root.render(
                    <Provider store={proxyStore}>
                        <PlayerUIWrapper metaData={payload.metadata} playerSelectors={payload.videoInfo.playerSelectors}/>
                    </Provider>
                );
            }
        }).catch(err => {
            console.error('[UIController] proxyStore.ready() failed:', err);
        });
    }

    updateUI(metaData: VideoMetaData): void {
        // Skeleton implementation
    }
    initateDownload(videoInfo: VideoInfo): void {
        // Skeleton implementaion
    }

    async renderPlayerUI(videoInfoAndMetadata: VideoInfoAndMetadata): Promise<void> {
        const { metadata, videoInfo } = videoInfoAndMetadata;
        UIController.renderUI(UIType.PLAYER, { metadata, videoInfo });
    }

}

const PlayerUIWrapper: React.FC<{ metaData: VideoMetaData, playerSelectors: string[] }> = ({ metaData, playerSelectors }) => {

    const { currentTheme } = useSelector((state: any) => state.UIConfigurations);
    const dispatch = useDispatch();
    const shouldShowPlayerUi = metaData && metaData.formats &&
        ((Array.isArray(metaData.formats.videoFormats) && metaData.formats.videoFormats.length) ||
            (Array.isArray(metaData.formats.audioFormats) && metaData.formats.audioFormats.length));

    const handleDownloadAttempt = (format: any) => {
        chrome.runtime.sendMessage({ 
            type: MESSAGE_TYPES.VIDEO_DOWNLOAD_STARTED,
            payload: {
                format,
                downloadSource: TELEMETRY_LABEL.IN_VIDEO_DOWNLOAD
            }
        });
    };

    useEffect(() => {
        document.documentElement.setAttribute('data-gen-theme', currentTheme);
    },[currentTheme]);

    return (
        <>
            {shouldShowPlayerUi && <DownloadMenu metaData={metaData} playerSelectors={playerSelectors} onDownloadAttempt={handleDownloadAttempt} key={metaData.videoDetails.videoId}/>}
        </>
    );
};

const uiController = new UIController();
export default uiController;