import React, { useState, useEffect, useLayoutEffect, useRef } from 'react';
import FomatsList from './FormatsList';
import { AudioFormat, VideoFormat, VideoMetaData } from '../../interfaces';
import Icon from './common/Icon';
import { DOWNLOAD_TYPE, AUDIO_BITRATE, HD_QUALITIES, HD_TEXT, MESSAGE_TYPES, REDUX_ACTIONS, OFFSCREEN_MESSAGE_TYPES } from '../../constants';
import '../common/styles/eulaPopup.scss';
import { useSelector, useDispatch } from 'react-redux';
import ProgressBar from './ProgressBar';
import { DOWNLOAD_STATE, ProgressBarVariant } from '../../interfaces';
import { VideoMediaManagerUI } from '../../utils/VideoMediaManagerUI';
import { TELEMETRY_LABEL, TELEMETRY_ACTION, TELEMETRY_EVENT_TYPES, TELEMETRY_ORIGIN } from '../../telemetry/telemetryConstants';
import TelemetryUtils from '../../telemetry/telemetryUtils';
import { isRtlEnvironment } from '../../utils/LocaleUtils';
import UiUtils from '../../utils/UiUtils';

interface DownloadButtonProps {
    metaData: VideoMetaData;
    onDownloadAttempt: (format: any) => void;
    fromPopover?: boolean;
    downloadStatus?: any; // Accept downloadStatus as an optional prop
    forceCloseFormatsList?: boolean; // Force close the formats list dropdown
    onFormatSelected?: any;
    defaultFormat?: any;
    onMoreIconClicked?: any;
}

function sendShowEulaPopupMessage() {
    chrome.runtime.sendMessage({ 
        type: MESSAGE_TYPES.SHOW_EULA_POPUP
    });
}

const DownloadButton: React.FC<DownloadButtonProps> = (props) => {
    const { metaData, fromPopover, onDownloadAttempt, downloadStatus: propDownloadStatus, forceCloseFormatsList } = props;
    const { formats } = metaData;
    const [showFormatsList, setShowFormatsList] = useState<any>(false);
    const defaultSelected = props.defaultFormat ? props.defaultFormat : formats.videoFormats[0];
    const [selectedFormat, setSelectedFormat] = useState<any>(defaultSelected);
    const downloadButtonRef = useRef(null);
    const eulaAcceptanceDetails = useSelector((state: any) => state.eulaAcceptanceDetails);
    const eulaAccepted = eulaAcceptanceDetails.isEulaAccepted;
    const [formatListTop, setShowFormatsListTop] = useState<number>(0);
    const formatListRef = useRef(null);
    const downloadMenuPos = !fromPopover ? { top: '33px', right: '-44px'}: {top: `${formatListTop? formatListTop: 24}px`};

    const videoId = metaData.videoDetails.videoId;
    // Use propDownloadStatus if provided, else fallback to Redux
    const downloadStatus = propDownloadStatus !== undefined ? propDownloadStatus : useSelector((state: any) => {
        const status = VideoMediaManagerUI.getDownloadStatus(videoId, state.downloadInitiatedVideos.downloadInitiatedVideos)
        return status;
    });
    const strings = {
        download: chrome.i18n.getMessage('download')
    };
    const dispatch = useDispatch();

    const handleClickOutside = (event) => {
        if (downloadButtonRef.current && !downloadButtonRef.current.contains(event.target)) {
            setShowFormatsList(false);
        }
    };

    const getVideoValue = (selectedFormat: VideoFormat) => {
        const qualityLabel = (selectedFormat as any).qualityLabel;
        return selectedFormat.isHDFormat ? `${qualityLabel} ${HD_TEXT}` : qualityLabel;
    }

    const sendResolutionSelectionTelemetry = (downloadType: string, selectedFormat: VideoFormat | AudioFormat) => {
        const label = fromPopover ? TELEMETRY_LABEL.MAIN_MENU : TELEMETRY_LABEL.IN_VIDEO_DOWNLOAD;
        const action = downloadType === DOWNLOAD_TYPE.VIDEO ? TELEMETRY_ACTION.VIDEO : TELEMETRY_ACTION.AUDIO;
        const value = downloadType === DOWNLOAD_TYPE.VIDEO 
            ? getVideoValue(selectedFormat as VideoFormat)
            : `${(selectedFormat as any).audioBitrate.toString()}${AUDIO_BITRATE.KBPS}`;
        
        // Send telemetry via telemetryUtils
        TelemetryUtils.sendTelemetryMessageForUI(TELEMETRY_EVENT_TYPES.RESOLUTION_SELECTION, { label, action, value });
    };

    useEffect(() => {
        if (showFormatsList) {
            document.addEventListener('click', handleClickOutside);
        } else {
            document.removeEventListener('click', handleClickOutside);
        }

        return () => {
            document.removeEventListener('click', handleClickOutside);
        };
    }, [showFormatsList]);

    // Close formats list when forced to close
    useEffect(() => {
        if (forceCloseFormatsList) {
            setShowFormatsList(false);
        }
    }, [forceCloseFormatsList]);

    useLayoutEffect(() => {
        if(!fromPopover || !showFormatsList) return;
        const buttonElement = downloadButtonRef.current as HTMLDivElement;
        const containerElement = document.querySelector('.popup-container') as HTMLDivElement;
        if (!containerElement || !buttonElement) {
            setShowFormatsList((v) => !v);
            return;
        }

        const buttonRect = buttonElement.getBoundingClientRect();
        const containerRect = containerElement.getBoundingClientRect();
        const viewportHeight = window.innerHeight;
        const visibleContainerTop = Math.max(containerRect.top, 0);
        const visibleContainerBottom = Math.min(containerRect.bottom, viewportHeight);

        const spaceBelow = visibleContainerBottom - buttonRect.bottom;
        const spaceAbove = buttonRect.top - visibleContainerTop;
        const buttonHeight = buttonRect.height;
        const paddingBelow = 0;
        const paddingAbove = 0.5;
        const dropdownHeight = formatListRef.current.offsetHeight;

        if (spaceAbove >= dropdownHeight) {
            setShowFormatsListTop(-dropdownHeight - paddingAbove);
          } else if(spaceBelow >= dropdownHeight) {
            setShowFormatsListTop(buttonHeight+ paddingBelow);
          } else {
            const scrollHeight = containerElement.scrollHeight;
            containerElement.style.height = `${scrollHeight + 20}px`;
          }
          
        // reset container styling when FormatsList is hidden
        return () => {
          if (containerElement) {
            containerElement.style.height = 'auto';
          }
        };
    },[showFormatsList]);

    const handleOptionChange = (downloadType, averageBitrate) => {
        const selectFormatList = downloadType === DOWNLOAD_TYPE.VIDEO ? formats.videoFormats : formats.audioFormats;
        const selectedFormat = selectFormatList.find(format => format.averageBitrate === averageBitrate);
        setSelectedFormat(selectedFormat);
        setShowFormatsList(false);

        // Send telemetry for resolution/audio selection
        sendResolutionSelectionTelemetry(downloadType, selectedFormat);
        props.onFormatSelected && props.onFormatSelected(selectedFormat)
    };

    const handleDropdownClick = (e) => {
        props.onMoreIconClicked && props.onMoreIconClicked(!showFormatsList);
        setShowFormatsList((v) => !v);
        
        // Send telemetry for menu dropdown click based on context
        if (!showFormatsList) { // Only when opening the dropdown
            const origin = fromPopover ? TELEMETRY_ORIGIN.POPUP : TELEMETRY_ORIGIN.IN_VIDEO;
            TelemetryUtils.sendTelemetryMessageForUI(TELEMETRY_EVENT_TYPES.MENU_CLICK, { origin });
        }
    };

    const getMediaData = () => {
        if (selectedDownloadFormat === DOWNLOAD_TYPE.AUDIO) {
            return {
                audioFormat: selectedFormat,
                videoDetails: metaData.videoDetails,
            }
        }
        return {
            videoFormat: selectedFormat,
            audioFormat: formats.audioFormats[0],
            videoDetails: metaData.videoDetails,
        }
    }

    // Only check Redux store for EULA acceptance/dismissal. If not accepted or dismissed, trigger EULA popup.
    const handleDownloadClick = async (e) => {
        if(e.target.className === 'expand-more-icon') return;
        showFormatsList && setShowFormatsList(false);
        const mediaData = getMediaData();
        
        // Send telemetry for download button click based on context
        const origin = fromPopover ? TELEMETRY_ORIGIN.POPUP : TELEMETRY_ORIGIN.IN_VIDEO;
        TelemetryUtils.sendTelemetryMessageForUI(TELEMETRY_EVENT_TYPES.DOWNLOAD_CLICK, { origin });
        
        // Only Redux store is checked for EULA state
        if (!eulaAccepted) {
            const downloadSource = fromPopover ? TELEMETRY_LABEL.MAIN_MENU : TELEMETRY_LABEL.IN_VIDEO_DOWNLOAD;
            sendShowEulaPopupMessage();
            dispatch({
                type: REDUX_ACTIONS.EULA_NOT_ACCEPT_DOWNLOAD_CLICK,
                payload: { 
                    format: mediaData,
                    downloadSource: downloadSource
                }
            });
            return;
        }
        if (onDownloadAttempt) {
            onDownloadAttempt(mediaData);
        }
    };


    const selectedDownloadFormat = selectedFormat.qualityLabel ? DOWNLOAD_TYPE.VIDEO : DOWNLOAD_TYPE.AUDIO;
    const qualityFormat = selectedDownloadFormat === DOWNLOAD_TYPE.VIDEO ? selectedFormat.qualityLabel : selectedFormat.audioBitrate;
    const qualityFormatDisplayText = selectedDownloadFormat === DOWNLOAD_TYPE.VIDEO ? qualityFormat : `${qualityFormat} ${AUDIO_BITRATE.KBPS}`;
    const isHdFormat = selectedFormat.isHDFormat;
    const iconPath = selectedDownloadFormat === DOWNLOAD_TYPE.VIDEO ? `/assets/images/menu-camera.svg` : `/assets/images/menu-audio.svg`;

    const isRtl = isRtlEnvironment();
    const ltrChunk = isRtl 
        ? `${isHdFormat ? `${HD_TEXT} ` : ''}${qualityFormatDisplayText}`  // RTL: "HD 1080p"
        : `${qualityFormatDisplayText}${isHdFormat ? ` ${HD_TEXT}` : ''}`;  // LTR: "1080p HD"

    return (
        <>
        <div
            className={`download-button-wrap${fromPopover ? ' popover-style' : ''}`}
            ref={downloadButtonRef}
        >
            {downloadStatus && (downloadStatus.downloadState === DOWNLOAD_STATE.STARTED || downloadStatus.downloadState === DOWNLOAD_STATE.CANCELLATION_IN_PROGRESS) && (
                <ProgressBar progressPercentage={downloadStatus.progressPercentage} videoId={videoId} videoAttributes={downloadStatus.videoAttributes} variant={fromPopover ? ProgressBarVariant.POPUP : ProgressBarVariant.PLAYER}
                status={downloadStatus} />
            )}
            {(
                !downloadStatus ||
                downloadStatus.downloadState === DOWNLOAD_STATE.NOT_STARTED ||
                downloadStatus.downloadState === DOWNLOAD_STATE.CANCELLED ||
                downloadStatus.downloadState === DOWNLOAD_STATE.EULA_NOT_ACCEPTED ||
                UiUtils.isErrorState(downloadStatus.downloadState)
            ) && (
                <section
                    className='download-button-container'
                    onClick={handleDownloadClick}
                >
                    <Icon iconUrl={iconPath} className='camera-icon' />
                    <span className='download-format-text' dir={isRtl ? 'ltr' : 'auto'}>
                        {isRtl ? (
                            <>
                              <span dir="ltr" className="ltr-chunk">{ltrChunk}</span>{' '}
                              <span dir="rtl" className="rtl-chunk">{strings['download']}</span>
                            </>
                        ) : (
                            <>
                              <span>{strings['download']}</span>{' '}
                              <span>{ltrChunk}</span>
                            </>
                        )}
                    </span>
                    <span className='text-separator'></span>
                    <span
                        className='download-size-text'
                    >
                        {selectedFormat.contentLengthInKbOrMbOrGb} {selectedFormat.contentLengthUnit}
                    </span>
                    <Icon iconUrl="/assets/images/expand-more.svg" className='expand-more-icon' onClick={handleDropdownClick} />
                </section>
            )}
            {showFormatsList && <FomatsList onChange={handleOptionChange} formats={formats} selectedFormat={qualityFormat} 
            elementPosition={downloadMenuPos} ref={formatListRef}/>} 
        </div>
        </>
    );
};

export default DownloadButton;