import React from 'react';

interface IconProps {
  iconUrl: string;
  onClick?: (e: any) => void;
  className?: string;
  title?: string;
}

const Icon: React.FC<IconProps> = ({ iconUrl, onClick, className, title }) => {
  const extnImgUrl = chrome.runtime.getURL(iconUrl);
  return (
    <img
      className={className}
      onClick={onClick}
      role="button"
      title={title}
      src={extnImgUrl}
      alt={title || 'icon'}
      data-testid={className}
      data-icon-url={iconUrl}
    />
  );
};

export default Icon;
