import type { DOMParser, IParsingRules } from './interfaces';

export class VideoDOMParser implements DOMParser {
  private playerSelectors: string[] = [];

  constructor(domParsingRules: string[] = []) {
    this.playerSelectors = domParsingRules;
  }

  public hasPlayer(): boolean {
    for (const selector of this.playerSelectors) {
      const found = document.querySelector(selector);
      if (found) {
        return true;
      }
    }
    // TODO: Telemetry will be sent here in the future to report failed selectors for CDN updates.
    return false;
  }

  public getVideoId(parsingRules: IParsingRules, url: string): string | null {
    if (!url || !parsingRules?.urlParsingRules?.length) {
      return null;
    }
    for (const rule of parsingRules.urlParsingRules) {
      let regexStr = rule.videoId;
      const regex = new RegExp(regexStr);
      const match = regex.exec(url);
      if (match && match[1]) {
        return match[1];
      }
    }
    return null;
  }

  public getPlayerSelectors(): string[] {
    return this.playerSelectors;
  }
}
