import { ROOT_ELEMENT_ID } from '../constants';
import { DOWNLOAD_STATE, MetadataReduxState, PlayerOffset } from '../interfaces';
import FontFaceInjector from './FontFaceInjector';

export class UiUtils {

    static createRootElement(id = ROOT_ELEMENT_ID) {
        let rootElement = document.getElementById(id);
        if (document.getElementById(ROOT_ELEMENT_ID)) return rootElement;
        rootElement = document.createElement('div');
        rootElement.classList.add('notranslate');
        // inject Roboto font-face for any UI root
        FontFaceInjector.injectFontFace();
        rootElement.id = id;
        document.documentElement.appendChild(rootElement);
        return rootElement;
    }

    static getPlayerOffset(playerSelectors): PlayerOffset {
        const playerElement = this.getPlayerElement(playerSelectors);
        if (!playerElement) {
            return;
        }
        if (playerElement) {
            let rect = playerElement.getBoundingClientRect();
            let scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;
            let scrollTop = window.pageYOffset || document.documentElement.scrollTop;
            return {
                top: rect.top + scrollTop,
                left: rect.left + scrollLeft + playerElement.clientWidth,
                right: document.documentElement.offsetWidth - rect.right
            }
        }
    }

    static getPlayerElement(playerSelectors:string[]) {
        for (const selector of playerSelectors) {
            const element = document.querySelector(selector);
            if (element) {
                return element;
            }
        }
        return null;
    }

    static getExtensionVersion(): Promise<string> {
        return new Promise((resolve, reject) => {
            try {
                chrome.runtime.sendMessage({ type: "GET_EXTENSION_VERSION" }, (response) => {
                    if (response && response.version) {
                        resolve(response.version);
                    }
                });
            } catch (error) {
                reject(error);
            }
        });
    }

    static getProviderFromId(videoId: string, metadataValues: MetadataReduxState): string {
        for (const provider in metadataValues) {
            if (metadataValues[provider].hasOwnProperty(videoId)) {
              return provider;
            }
        }
    }

    /**
     * Combines nested objects within the provided metadata into a single flattened object.
     * 
     * @param metaData - An object containing nested objects to be merged.
     * @returns A new object that merges all nested objects within the `metaData` parameter.
     *          If a value in `metaData` is not an object or is null, it is ignored.
     */
    static getMetadataObject(metaData: MetadataReduxState) {
        let data = {};
        Object.values(metaData).forEach(value => {
            if (typeof value === 'object' && value !== null) {
                data = { ...data, ...value };
            }
        });
        return data;
    }

    /**
     * Determines if a given download state represents an error condition.
     * 
     * This method checks if the provided download state is one of the predefined error states
     * that indicate a download has failed due to network issues, media processing errors,
     * or service-related problems.
     * 
     * @param downloadState - The download state to check for error condition
     * @returns {boolean} True if the download state represents an error (NETWORK_ERROR, MEDIA_ERROR, or SERVICE_ERROR), false otherwise
     * 
     * @example
     * ```typescript
     * const helper = new HelperUtils();
     * 
     * // Check if download failed due to network error
     * const isError = helper.isErrorState(DOWNLOAD_STATE.NETWORK_ERROR); // returns true
     * 
     * // Check if download completed successfully
     * const isError2 = helper.isErrorState(DOWNLOAD_STATE.COMPLETED); // returns false
     * ```
     * 
     * @see {@link ERROR_STATES} - The array of error states used for comparison
     * @see {@link DOWNLOAD_STATE} - Enum containing all possible download states
     */
    static isErrorState(downloadState: DOWNLOAD_STATE): boolean {
        return [DOWNLOAD_STATE.NETWORK_ERROR, DOWNLOAD_STATE.MEDIA_ERROR, DOWNLOAD_STATE.SERVICE_ERROR].includes(downloadState);
    }
}

export default UiUtils;