import React, { useEffect, useState, forwardRef } from 'react';
import Icon from './common/Icon';
import { INFORMATION_LINK, INFO_HD_TEXT } from '../../constants';
import UiUtils from '../../utils/UiUtils';
import { useSelector } from 'react-redux';
import { isRtlEnvironment } from '../../utils/LocaleUtils';

interface InfoPopupProps {
    onMouseEnter: () => void;
}

const InfoPopup = forwardRef((props:InfoPopupProps, ref) => {  
    const strings = {
        appName: chrome.i18n.getMessage('appName'),
        infoDescription: chrome.i18n.getMessage('extnInfoDescription'),
        version: chrome.i18n.getMessage('ver'),
        learnMore: chrome.i18n.getMessage('learnMore'),
        copyright: chrome.i18n.getMessage('copyright')
    };
    const {onMouseEnter} = props;
    const [extnVersion, setExtensionVersion] = useState<string>('');
    const { currentTheme } = useSelector((state: any) => state.UIConfigurations);
    const versionText = `${strings.version} ${extnVersion}`;
    const isRtl = isRtlEnvironment();

    const renderInfoDescription = () => {
        // For RTL locales, ensure the token "HD" stays LTR and in the correct visual order
        if (!isRtl) {
            return strings.infoDescription;
        }
        const parts = strings.infoDescription.split('HD');
        if (parts.length === 1) {
            return strings.infoDescription;
        }
        return (
            <>
                {parts.map((part, index) => (
                    <React.Fragment key={index}>
                        {part}
                        {index < parts.length - 1 && (
                            <span dir="ltr" className="ltr-inline">{INFO_HD_TEXT}</span>
                        )}
                    </React.Fragment>
                ))}
            </>
        );
    };

    useEffect(() => {
        if (extnVersion) return;
        const getExtensionVersion = async () => {
            try {
                const version = await UiUtils.getExtensionVersion();
                setExtensionVersion(version);
            } catch (e) {
            }
        };

        getExtensionVersion();
    }, []);
   
    return (
        // @ts-ignore
        <div className="info-popup-container" ref={ref} onMouseEnter={onMouseEnter}>
            <div>
                <Icon iconUrl="/assets/images/logo.svg" className='info-gen-logo' />
            </div>
            <div className="extn-title">
                {strings.appName}
            </div>
            <div className="extn-version">
                {versionText}
            </div>
            <div className="info-desc" dir={isRtl ? 'rtl' : 'auto'}>
                {renderInfoDescription()}
            </div>
            <a className="info-learn-more" href={INFORMATION_LINK}
                target="_blank"
                rel="noopener noreferrer">
                {strings.learnMore}
            </a>
            <div className='info-copyright'>
                <Icon iconUrl={`/assets/images/${currentTheme}/gen.svg`} className='info-gen-logo' />
                <span className='copyright-text'>{strings.copyright}</span>
            </div>
        </div>
    );
});

export default InfoPopup;
