import React, { useState, useEffect, useRef, useCallback } from 'react';
import DownloadButton from './DownloadButton';
import { VideoMetaData, ProgressBarVariant, DOWNLOAD_STATE } from '../../interfaces';
import Icon from './common/Icon';
import '../common/styles/player.scss';
import UiUtils from '../../utils/UiUtils';
import { isRtlEnvironment } from '../../utils/LocaleUtils';
import useEventListener from '../components/hooks/useEventListener';
import InfoPopup from './InfoPopup';
import { INITIAL_HIDE_TIMEOUT, MINIMUM_SUPPORTED_PLAYER_DIMENSION, PLAYER_MENU_RIGHT_PADDING, PLAYER_MENU_TOP_PADDING } from '../../constants';
import ProgressBar from './ProgressBar';
import { useSelector } from 'react-redux';
import { VideoMediaManagerUI } from '../../utils/VideoMediaManagerUI';
import { TELEMETRY_EVENT_TYPES, TELEMETRY_ORIGIN } from '../../telemetry/telemetryConstants';
import TelemetryUtils from '../../telemetry/telemetryUtils';

interface DownloadMenuProps {
    metaData: VideoMetaData;
    playerSelectors: string[];
    onDownloadAttempt: (format: any) => void;
}

const DownloadMenu: React.FC<DownloadMenuProps> = (props) => {
    const { metaData, playerSelectors, onDownloadAttempt } = props;
    const [right, setRight] = useState<any>(0);
    const [left, setLeft] = useState<any>('auto');
    const [top, setTop] = useState<any>(0);
    const [showMenu, setShowMenu] = useState(!document.fullscreen);
    const [showInfoPopup, setShowInfoPopup] = useState(false);
    const downloadMenuRef = useRef(null);
    const infoPopupRef = useRef(null);
    const playerElementRef = useRef(null);
    playerElementRef.current = UiUtils.getPlayerElement(playerSelectors);
    const [defaultFormat, setDefaultFormat] = useState<any>(null);
    const { currentTheme } = useSelector((state: any) => state.UIConfigurations);
    const formatRef = useRef(null);

    const setMenuVisible = useCallback(() => {
        !document.fullscreen && setShowMenu(true);
    },[metaData.videoDetails.videoId]);

    const setMenuHidden = useCallback(() => {
        setShowMenu(false);
        setShowInfoPopup(false);
    },[metaData.videoDetails.videoId]);

    const onFullscreenChange = useCallback(() => {
        if (document.fullscreen) {
            setShowMenu(false);
        }
    },[metaData.videoDetails.videoId]);

    const handleClickOutside = useCallback((event) => {
        if (infoPopupRef.current && !infoPopupRef.current.contains(event.target)) {
            setShowInfoPopup(false);
        }
    },[metaData.videoDetails.videoId]);

    const handleShowExtnInfoPopup = (e) => {
        e.stopPropagation();
        setShowInfoPopup(!showInfoPopup);
        // Send telemetry for info icon click in in-video overlay
        TelemetryUtils.sendTelemetryMessageForUI(TELEMETRY_EVENT_TYPES.INFO_CLICK, { origin: TELEMETRY_ORIGIN.IN_VIDEO });
    };

    // Get download status from Redux and flatten it for this videoId (just like popup)
    const downloadInitiatedVideos = useSelector((state: any) => state.downloadInitiatedVideos.downloadInitiatedVideos) || {};
    const { status } = VideoMediaManagerUI.getSingleVideoStatus(metaData, downloadInitiatedVideos);

    useEventListener('mouseenter', setMenuVisible, playerElementRef.current as HTMLElement);
    useEventListener('mouseleave', setMenuHidden, playerElementRef.current as HTMLElement);
    useEventListener('fullscreenchange', onFullscreenChange, document);
    useEventListener('click', handleClickOutside, document);

    const onMoreIconClicked = (isFormatShown) => {
        formatRef.current = isFormatShown;
    }

    useEffect(() => {
        if(!playerElementRef.current) return;

        const resizeObserver = new ResizeObserver((entries) => {
            for (let entry of entries) {
                const { width, height } = entry.contentRect;
                if(width < MINIMUM_SUPPORTED_PLAYER_DIMENSION.WIDTH || height < MINIMUM_SUPPORTED_PLAYER_DIMENSION.HEIGHT) {
                    setShowMenu(false);
                    return;
                }
            }
            const playerOffset = UiUtils.getPlayerOffset(playerSelectors);
            if (!playerOffset) return;
            const isRtl = isRtlEnvironment();
            const rect = (playerElementRef.current as HTMLElement).getBoundingClientRect();
            const menuRightPosition = isRtl ? 'auto' : `${playerOffset.right + PLAYER_MENU_RIGHT_PADDING}px`;
            const menuLeftPosition = isRtl ? `${rect.left + PLAYER_MENU_RIGHT_PADDING}px` : 'auto';
            const menuTopPosition = `${playerOffset.top + PLAYER_MENU_TOP_PADDING}px`;
            setRight(menuRightPosition);
            setLeft(menuLeftPosition);
            setTop(menuTopPosition);
        });
        resizeObserver.observe(playerElementRef.current);

        return () => {
            resizeObserver.disconnect();
        }
    }, [metaData.videoDetails.videoId,showMenu]);

    useEffect(() => {
        !document.fullscreen && setShowMenu(true);
        const hideTimeout = setTimeout(() => {
            !formatRef.current && setShowMenu(false)
        }, INITIAL_HIDE_TIMEOUT);
        return () => {
            clearTimeout(hideTimeout);
        }
    }, [metaData.videoDetails.videoId]);

    const onFormatSelected = (format) => {
        setDefaultFormat(format)
    }

    const strings = {
        moreInformation: chrome.i18n.getMessage('moreInformation'),
    };

    return (
        (showMenu) && (
            <>
                <div className='download-menu-container' style={{ right, left, top }} ref={downloadMenuRef} onMouseEnter={() => { setShowMenu(true); }}>
                    {status && status.downloadState === DOWNLOAD_STATE.STARTED ? (
                        <ProgressBar 
                            progressPercentage={status.progressPercentage} 
                            videoId={metaData.videoDetails.videoId}
                            videoAttributes={status.videoAttributes}
                            variant={ProgressBarVariant.PLAYER} 
                            status={status}
                        />
                    ) : (
                        <DownloadButton onMoreIconClicked={onMoreIconClicked} metaData={metaData} onDownloadAttempt={onDownloadAttempt} forceCloseFormatsList={showInfoPopup} onFormatSelected={onFormatSelected} defaultFormat={defaultFormat}/>
                    )}
                    <Icon iconUrl={`/assets/images/${currentTheme}/info.svg`} className='info-icon' title={strings.moreInformation}
                    aria-label={strings.moreInformation}onClick={handleShowExtnInfoPopup} />
                    {showInfoPopup && <InfoPopup ref={infoPopupRef} onMouseEnter={() => { setShowInfoPopup(true) }}/>} 
                </div>
            </>
        )
    );
};

export default DownloadMenu;