export class DomObserver {
  private observer: MutationObserver | null;
  constructor() {
    this.observer = null as MutationObserver | null;
  }
  /**
   * Observes changes in the DOM to detect the presence of specific player elements
   * and triggers video information and metadata retrieval when a matching element is found.
   *
   * @param playerElements - An array of CSS selector strings representing the player elements to observe.
   * @param urlParsingRules - An object containing rules for parsing video URLs and metadata.
   *
   * The method sets up a `MutationObserver` to monitor changes in the DOM's child elements
   * and subtree. When a matching player element is detected, it invokes the `fetchVideoInfoAndMetadata`
   * method and disconnects the observer to stop further monitoring.
   */
  observeDom(targetElements: string[], onTargetElementFound: () => void): void {
    const targetNode = document.body;
    const config = { childList: true, subtree: true };
    const callback: MutationCallback = (mutationsList, observer) => {
      for (const mutation of mutationsList) {
        if (mutation.type === 'childList') {
          const targetElement = targetElements
            .map((selectorRule) => document.querySelector(selectorRule))
            .find((element) => element !== null);
          if (targetElement) {
            onTargetElementFound();
            break;
          }
        }
      }
    };

    this.observer = new MutationObserver(callback);
    this.observer.observe(targetNode, config);
  }

  /**
   * Stops observing changes in the DOM by disconnecting the MutationObserver.
   * This method should be called to clean up resources when DOM observation is no longer needed.
   */
  unobserveDom() {
    if (!this.observer) {
      return;
    }
    this.observer.disconnect();
    this.observer = null;
  }
}