import { MESSAGE_TYPES } from '../constants';
import { TELEMETRY_EVENT_TYPES } from './telemetryConstants';

/**
 * Utility functions for sending telemetry events from UI components.
 * This centralizes telemetry message passing to avoid duplicating the logic.
 */
class TelemetryUtils {
    /**
     * Generic method to send telemetry messages from UI components to the background script.
     * @param eventType - The type of telemetry event (use TELEMETRY_EVENT_TYPES constants)
     * @param additionalPayload - Additional payload data for the event (optional)
     */
    static sendTelemetryMessageForUI(eventType: string, additionalPayload?: any): void {
        chrome.runtime.sendMessage({
            type: MESSAGE_TYPES.SEND_TELEMETRY,
            payload: {
                eventType,
                ...additionalPayload
            }
        });
    }
}

export default TelemetryUtils;
