import { MESSAGE_TYPES, VIDEO_PROVIDER } from './constants';
import {  VideoMetaData} from './interfaces';

class MediaMetaDataExtractorCS  {

    /**
   * Gets video metadata from background.
   */
    async getVideoMetaData(videoId: string, providerName: VIDEO_PROVIDER): Promise<VideoMetaData> {
        const response = await chrome.runtime.sendMessage({
            type: MESSAGE_TYPES.FETCH_METADATA,
            payload: {
                videoId,
                providerName
            }
          });
        return response.data;
    }
}
const mediaMetaDataExtractorCS = new MediaMetaDataExtractorCS();
export default mediaMetaDataExtractorCS;