import React, { useEffect, forwardRef }from 'react';
import Icon from './common/Icon';
import { FormatsData, ElementPosition} from '../../interfaces';
import { AUDIO_BITRATE, HD_QUALITIES, HD_TEXT, MEDIA_SIZE } from '../../constants';
import { useSelector } from 'react-redux';

interface FomatsListProps {
    formats: FormatsData;
    selectedFormat: any;
    onChange: (type: string, b: number) => void;
    elementPosition?: ElementPosition;
}

const FomatsList = forwardRef((props:FomatsListProps,ref) => { 
    const { formats, selectedFormat, onChange, elementPosition } = props;
    const { audioFormats, videoFormats } = formats;
    const shouldShowVideoFormatsSection = Array.isArray(videoFormats) && videoFormats.length;
    const shouldShowAudioFormatsSection = Array.isArray(audioFormats) && audioFormats.length;
    const { currentTheme } = useSelector((state: any) => state.UIConfigurations);

    const strings = {
        downloadVideo: chrome.i18n.getMessage('downloadVideo'),
        downloadAudioOnly: chrome.i18n.getMessage('downloadAudioOnly')
    };

    const handleOptionChange = (downloadType, averageBitrate) => {
        onChange(downloadType, averageBitrate);
    };

    const renderVideoFormatsSection = () => {
        return (<section className='video-formats-list'>
            <div className="download-type">{strings['downloadVideo']}</div>
            <section className='format-options'>
                {videoFormats.map((videoFormat, index) => (
                    <div key={`video-${index}`} className='format-option' onClick={() =>handleOptionChange('video', videoFormat.averageBitrate)} data-testid={`video-format-${index}`}>
                        <div className='radio-wrap'>
                            <section className='radio-label'>
                                <Icon iconUrl={`/assets/images/${currentTheme}/camera.svg`} className='camera-icon' />
                                <label htmlFor={`video-${index}`}>
                                    <span className='format-type'>{videoFormat.qualityLabel}{videoFormat.isHDFormat ? ` ${HD_TEXT}`: ``}</span>
                                    <span className='text-separator'></span>
                                    <span className='download-size'>{videoFormat.contentLengthInKbOrMbOrGb} {videoFormat.contentLengthUnit}</span>
                                </label>
                            </section>
                            <input type="radio" id={`video-${index}`} name="video-format" value={videoFormat.qualityLabel}
                                defaultChecked={selectedFormat === videoFormat.qualityLabel}
                                data-testid={`video-radio-${index}`} />
                        </div>
                    </div>
                ))}
            </section>
        </section>);
    }

    const renderAudioFormatsSection = () => {
        return (<section className='audio-formats-list' >
            <div className="download-type">{strings['downloadAudioOnly']}</div>
            <section className='format-options'>
                {audioFormats.map((audioFormat, index) => (
                    <div key={`audio-${index}`} className='format-option' onClick={() => handleOptionChange('audio', audioFormat.averageBitrate)} data-testid={`audio-format-${index}`}>
                        <div className='radio-wrap'>
                            <section className='radio-label'>
                                <Icon iconUrl={`/assets/images/${currentTheme}/speaker.svg`} className='speaker-icon' />
                                <label htmlFor={`audio-${index}`}>
                                    <span className='format-type'>{audioFormat.audioBitrate} {AUDIO_BITRATE.KBPS}</span>
                                    <span className='text-separator'></span>
                                    <span className='download-size'>{audioFormat.contentLengthInKbOrMbOrGb} {audioFormat.contentLengthUnit}</span>
                                </label>
                            </section>
                            <input type="radio" id={`audio-${index}`} name="video-format" value={audioFormat.audioBitrate}
                                defaultChecked={selectedFormat === audioFormat.audioBitrate}
                                data-testid={`audio-radio-${index}`} />
                        </div>
                    </div>
                ))}
            </section>
        </section>);
    }


    return (
        // @ts-ignore
        <div className='formats-list-container' style={elementPosition} ref={ref} data-testid="formats-list">
            {shouldShowVideoFormatsSection && renderVideoFormatsSection()}
            {shouldShowAudioFormatsSection && renderAudioFormatsSection()}
        </div>
    );
}
);

export default FomatsList;